import java.io.*; import java.util.*; class Result { public static String abbreviation(String a, String b) { int n = a.length(); int m = b.length(); boolean[][] dp = new boolean[n + 1][m + 1]; dp[0][0] = true; for (int i = 1; i <= n; i++) { char charA = a.charAt(i - 1); if (Character.isLowerCase(charA)) { dp[i][0] = dp[i - 1][0]; } else { dp[i][0] = false; } } for (int i = 1; i <= n; i++) { for (int j = 1; j <= m; j++) { char charA = a.charAt(i - 1); char charB = b.charAt(j - 1); if (Character.isUpperCase(charA)) { if (charA == charB) { dp[i][j] = dp[i - 1][j - 1]; } else { dp[i][j] = false; } } else { boolean deleted = dp[i - 1][j]; boolean capitalized = (Character.toUpperCase(charA) == charB) && dp[i - 1][j - 1]; dp[i][j] = deleted || capitalized; } } } return dp[n][m] ? "YES" : "NO"; } } public class Solution { public static void main(String[] args) throws IOException { BufferedReader bufferedReader = new BufferedReader(new InputStreamReader(System.in)); BufferedWriter bufferedWriter = new BufferedWriter(new FileWriter(System.getenv("OUTPUT_PATH"))); int q = Integer.parseInt(bufferedReader.readLine().trim()); for (int i = 0; i < q; i++) { String a = bufferedReader.readLine(); String b = bufferedReader.readLine(); String result = Result.abbreviation(a, b); bufferedWriter.write(result); bufferedWriter.newLine(); } bufferedReader.close(); bufferedWriter.close(); } }